def transform_rule(grid):
    """
    Hypothesis: 
    - Keep 1s where they are
    - For cells that are 0:
      - If (row + col) % 2 == 1: make it 2
      - If (row + col) % 2 == 0: make it 3
    """
    result = []
    for r, row in enumerate(grid):
        new_row = []
        for c, val in enumerate(row):
            if val == 1:
                new_row.append(1)
            elif val == 0:
                if (r + c) % 2 == 1:
                    new_row.append(2)
                else:
                    new_row.append(3)
            else:
                new_row.append(val)
        result.append(new_row)
    return result

