import collections

def flood_fill_is_interior(grid):
    """Flood fill from (0,0). Returns True for cells NOT reachable (i.e., interior of closed shape)"""
    rows = len(grid)
    cols = len(grid[0])

    # Find which cells are reachable from (0,0) by walking on 0s
    reachable = set()
    queue = collections.deque([(0, 0)])
    reachable.add((0, 0))

    while queue:
        r, c = queue.popleft()
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if (nr, nc) not in reachable and grid[nr][nc] == 0:
                    reachable.add((nr, nc))
                    queue.append((nr, nc))

    return reachable

