import collections

def predict_simple(grid):
    """
    Simple prediction:
    - Keep 1s as-is
    - 0s at minimum distance 1 from nearest 1:
        - if reachable from border → 2
        - else → 3 (interior)
    - Other 0s → stay 0
    """
    rows = len(grid)
    cols = len(grid[0])

    # Find min distance from each 0-cell to nearest 1
    min_dist = [[float('inf')]*cols for _ in range(rows)]
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1:
                min_dist[r][c] = 0

    # BFS to find distances from all 1s
    queue = collections.deque()
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1:
                min_dist[r][c] = 0
                queue.append((r, c))

    while queue:
        r, c = queue.popleft()
        d = min_dist[r][c] + 1
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and min_dist[nr][nc] > d:
                min_dist[nr][nc] = d
                queue.append((nr, nc))

    # Now determine what each cell becomes
    # First, which 0s are reachable from border?
    visited_border = []
    queue = collections.deque()

    # Start from ALL border cells that are 0
    for r in [0, rows-1]:
        for c in range(cols):
            if grid[r][c] == 0:
                visited_border.append((r, c))
                queue.append((r, c))
    for c in [0, cols-1]:
        for r in range(1, rows-1):
            if grid[r][c] == 0:
                if (r, c) not in visited_border:
                    visited_border.append((r, c))
                    queue.append((r, c))

    visited_set = set(visited_border)
    while queue:
        r, c = queue.popleft()
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if (nr, nc) not in visited_set and grid[nr][nc] == 0:
                    visited_set.add((nr, nc))
                    visited_border.append((nr, nc))
                    queue.append((nr, nc))

    # Build prediction
    result = []
    for r in range(rows):
        new_row = []
        for c in range(cols):
            val = grid[r][c]
            if val == 1:
                new_row.append(1)
            elif val == 0:
                # Check if reachable from border AND min dist is 1
                if (r, c) in visited_set and min_dist[r][c] == 1:
                    new_row.append(2)
                elif min_dist[r][c] >= 2:  # Interior far cell
                    # Is it truly enclosed? Check if NOT reachable from border
                    if (r, c) not in visited_set:
                        new_row.append(3)
                    else:
                        new_row.append(2)  # Reachable, so becomes 2
                else:
                    # Distance is infinite (no 1s nearby) but reachable
                    new_row.append(2)
            else:
                new_row.append(val)
        result.append(new_row)
    return result

