import collections

def predict_flood_fill_components(grid):
    """
    Prediction based on flood fill from left side:
    - Keep 1s as-is
    - Which 0s are reachable from LEFT side (col 0)?
        - If yes → fill them with 2
        - If no → they're blocked by 1s (become interior candidates)
    - Among those unreachable from left:
        - Find which ones are also unreachable from RIGHT side (col max)
        - Those are "truly enclosed" → fill with 3
        - Others stay 0
    """
    rows = len(grid)
    cols = len(grid[0])

    # Left-reachable: BFS from col 0
    left_reach = set()
    queue = collections.deque()

    for r in range(rows):
        if grid[r][0] == 0:
            left_reach.add((r, 0))
            queue.append((r, 0))

    while queue:
        r, c = queue.popleft()
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if (nr, nc) not in left_reach and grid[nr][nc] == 0:
                    left_reach.add((nr, nc))
                    queue.append((nr, nc))

    # Right-reachable: BFS from col max
    right_reach = set()
    queue = collections.deque()

    for r in range(rows):
        if grid[r][cols-1] == 0:
            right_reach.add((r, cols-1))
            queue.append((r, cols-1))

    while queue:
        r, c = queue.popleft()
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if (nr, nc) not in right_reach and grid[nr][nc] == 0:
                    right_reach.add((nr, nc))
                    queue.append((nr, nc))

    print("Left-reachable count:", len(left_reach))
    print("Right-reachable count:", len(right_reach))

    result = []
    for r in range(rows):
        new_row = []
        for c in range(cols):
            val = grid[r][c]
            if val == 1:
                new_row.append(1)
            elif val == 0:
                if (r, c) in left_reach:
                    new_row.append(2)  # Left-connected → 2
                elif (r, c) in right_reach:
                    new_row.append(3)  # Right-connected but not left → ??
                else:
                    new_row.append(0)  # Not reachable from either side
            else:
                new_row.append(val)
        result.append(new_row)
    return result

