import collections

def predict_dual_source(grid):
    """
    Dual source flood fill:
    - Left-reachable from col 0 → 2
    - Right-reachable from col max but NOT left-reachable → 3
    - Everything else → unchanged
    """
    rows = len(grid)
    cols = len(grid[0])

    # BFS from all border positions
    # Actually let's do full border reachability

    left_reach = set()
    queue = collections.deque()
    for r in range(rows):
        if grid[r][0] == 0:
            left_reach.add((r, 0))
            queue.append((r, 0))
    while queue:
        r, c = queue.popleft()
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if (nr, nc) not in left_reach and grid[nr][nc] == 0:
                    left_reach.add((nr, nc))
                    queue.append((nr, nc))

    right_reach = set()
    queue = collections.deque()
    for r in range(rows):
        if grid[r][cols-1] == 0:
            right_reach.add((r, cols-1))
            queue.append((r, cols-1))
    while queue:
        r, c = queue.popleft()
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if (nr, nc) not in right_reach and grid[nr][nc] == 0:
                    right_reach.add((nr, nc))
                    queue.append((nr, nc))

    print("Left-reachable:", sorted(left_reach)[:10], "...")
    print("Right-reachable:", sorted(right_reach)[:10], "...")
    print("Both reachable:", [(r,c) for r in range(rows) for c in range(cols) if (r,c) in left_reach and (r,c) in right_reach][:15])

    result = []
    for r in range(rows):
        new_row = []
        for c in range(cols):
            val = grid[r][c]
            if val == 1:
                new_row.append(1)
            elif val == 0:
                if (r, c) in left_reach and (r, c) not in right_reach:
                    new_row.append(2)
                elif (r, c) in right_reach and (r, c) not in left_reach:
                    new_row.append(3)
                else:
                    new_row.append(0)
            else:
                new_row.append(val)
        result.append(new_row)
    return result

