def predict_complete(grid):
    """
    Complete prediction based on analysis:
    1. Find cells reachable from column 0 (or left edge) via 0s: these become 2
    2. Find cells NOT reachable from column 0 via 0s but ARE surrounded by 1s: these become 3
    3. Everything else stays unchanged
    """
    rows = len(grid)
    cols = len(grid[0])

    # Step 1: Left-reachable from col 0
