    cols = len(grid[0])

    # Min distance from each 0 to nearest 1
    min_dist = [[float('inf')]*cols for _ in range(rows)]
    queue = collections.deque()

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1:
                min_dist[r][c] = 0
                queue.append((r, c))

    while queue:
        r, c = queue.popleft()
        d = min_dist[r][c] + 1
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and min_dist[nr][nc] > d:
                min_dist[nr][nc] = d
                queue.append((nr, nc))

    # Left-reachable from col 0
    left_reach = set()
    queue = collections.deque([(r, 0) for r in range(rows) if grid[r][0] == 0])

