        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and (nr, nc) not in left_reach and grid[nr][nc] == 0:
                left_reach.add((nr, nc))
                queue.append((nr, nc))

    result = []
    for r in range(rows):
        new_row = []
        for c in range(cols):
            val = grid[r][c]
            if val == 1:
                new_row.append(1)
            elif val == 0:
                md = min_dist[r][c]
                if (r,c) in left_reach:
