                                    dist[(nr, nc)] = True
                                    queue.append((nr, nc))
                    return set(dist.keys())

                reachable = bfs_from_cell((r,c))
                touches_tl = (0, 0) in reachable
                touches_tr = (0, cols-1) in reachable
                touches_bl = (rows-1, 0) in reachable
