def predict_cross_reach_strict(grid):
    """
    Strict rule:
    - Cell becomes 2 if it can reach BOTH left AND right edges via 0-path
      AND can reach BOTH top AND bottom edges via 0-path
    - Cell becomes 3 if it's strictly interior (can't reach ANY edge via 0-path)
    - Else stays original value
    """
    rows, cols = len(grid), len(grid[0])

    # Compute reachability from each edge
    def bfs_from_set(start_cells):
        dist = {}
        queue = collections.deque(start_cells)
        while queue:
            sr, sc = queue.popleft()
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = sr+dr, sc+dc
                if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == 0:
                    if (nr, nc) not in dist:
                        dist[(nr, nc)] = True
                        queue.append((nr, nc))
        return set(dist.keys())

    left_reachable = bfs_from_set({(r, 0) for r in range(rows)})
    right_reachable = bfs_from_set({(r, cols-1) for r in range(rows)})
    top_reachable = bfs_from_set({(0, c) for c in range(cols)})
    bottom_reachable = bfs_from_set({(rows-1, c) for c in range(cols)})

    result = []
    for r in range(rows):
        new_row = []
        for c in range(cols):
            val = grid[r][c]
            if val != 0:
                new_row.append(val)

            if val == 0:
                # Check crossing conditions
                crosses_lr = (r,c) in left_reachable and (r,c) in right_reachable
                crosses_tb = (r,c) in top_reachable and (r,c) in bottom_reachable

                # Crossing means reaching both pairs of opposite sides
                is_crossing = crosses_lr or crosses_tb

                # Check if strictly interior
                all_reachable = left_reachable | right_reachable | top_reachable | bottom_reachable
                is_interior = (r,c) not in all_reachable

                if is_interior:
                    new_row.append(3)
                elif is_crossing:
                    new_row.append(2)
                else:
                    new_row.append(0)  # Stays 0

